INSERT INTO learning_units (id, template_code, content_type, title, content_json, sort_order, enabled) VALUES
('unit_compare_17', 'phoneme-compare', 'PHONEME_COMPARE', '双元音 /ɔɪ/ 与 /əʊ/', '{"category":"双元音对比","title":"/ɔɪ/ 和 /əʊ/","description":"/ɔɪ/ 从圆唇后元音滑向 /ɪ/，/əʊ/ 从放松中央元音滑向 /ʊ/。","phonemes":[{"phonemeId":"p_v_15","ipa":"/ɔɪ/","description":"起点更圆，收向 /ɪ/。","mouth":{"type":"open"},"audioUrl":null,"examples":["boy","toy"]},{"phonemeId":"p_v_16","ipa":"/əʊ/","description":"起点更轻，结尾收圆。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["go","home"]}],"audioPairs":[{"left":"boy","right":"bow","tip":"boy 收到 /ɪ/，bow 收到 /ʊ/。"},{"left":"toy","right":"toe","tip":"听结尾滑向的位置不同。"}],"memoryTip":"/ɔɪ/ 像 boy，/əʊ/ 像 go。"}', 17, TRUE),
('unit_compare_18', 'phoneme-compare', 'PHONEME_COMPARE', '双元音 /ɪə/ 与 /eə/', '{"category":"双元音对比","title":"/ɪə/ 和 /eə/","description":"两者都滑向 /ə/，但起点不同：/ɪə/ 更高更收，/eə/ 更开。","phonemes":[{"phonemeId":"p_v_18","ipa":"/ɪə/","description":"从短 /ɪ/ 开始，轻轻放松到 /ə/。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["near","ear"]},{"phonemeId":"p_v_19","ipa":"/eə/","description":"从 /e/ 开始，开口更大。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["hair","care"]}],"audioPairs":[{"left":"near","right":"nair","tip":"near 起点更高更收。"},{"left":"ear","right":"air","tip":"air 的起点更开。"}],"memoryTip":"先听起点：near 更像 /ɪ/，air 更像 /e/。"}', 18, TRUE),
('unit_compare_19', 'phoneme-compare', 'PHONEME_COMPARE', '鼻音 /m/ 与 /n/', '{"category":"鼻音对比","title":"/m/ 和 /n/","description":"两者都是鼻音，/m/ 双唇闭合，/n/ 舌尖抵齿龈。","phonemes":[{"phonemeId":"p_c_18","ipa":"/m/","description":"双唇闭合，气流走鼻腔。","mouth":{"type":"closed"},"audioUrl":null,"examples":["man","summer"]},{"phonemeId":"p_c_19","ipa":"/n/","description":"舌尖抵住上齿龈，气流走鼻腔。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["no","nine"]}],"audioPairs":[{"left":"me","right":"knee","tip":"/m/ 闭双唇，/n/ 用舌尖。"},{"left":"sum","right":"sun","tip":"词尾听闭唇还是舌尖。"}],"memoryTip":"捏鼻子都会受阻，但嘴唇闭合的是 /m/。"}', 19, TRUE),
('unit_compare_20', 'phoneme-compare', 'PHONEME_COMPARE', '鼻音 /n/ 与 /ŋ/', '{"category":"鼻音对比","title":"/n/ 和 /ŋ/","description":"/n/ 在齿龈位置，/ŋ/ 在软腭位置，词尾 /ŋ/ 不要额外加 /ɡ/。","phonemes":[{"phonemeId":"p_c_19","ipa":"/n/","description":"舌尖抵齿龈。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["thin","win"]},{"phonemeId":"p_c_20","ipa":"/ŋ/","description":"舌后部抬向软腭。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["thing","wing"]}],"audioPairs":[{"left":"thin","right":"thing","tip":"thing 词尾舌后部抬起。"},{"left":"win","right":"wing","tip":"wing 不要读成 /wɪnɡ/。"}],"memoryTip":"/ŋ/ 的发力点在口腔后部。"}', 20, TRUE),
('unit_compare_21', 'phoneme-compare', 'PHONEME_COMPARE', '舌侧音 /l/ 与近音 /r/', '{"category":"近音对比","title":"/l/ 和 /r/","description":"/l/ 舌尖接触齿龈，/r/ 舌尖抬起但不接触。","phonemes":[{"phonemeId":"p_c_21","ipa":"/l/","description":"舌尖接触齿龈，气流从舌侧通过。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["light","lead"]},{"phonemeId":"p_c_22","ipa":"/r/","description":"舌尖后抬不接触，声音更圆。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["right","read"]}],"audioPairs":[{"left":"light","right":"right","tip":"/l/ 舌尖接触，/r/ 不接触。"},{"left":"lead","right":"read","tip":"听起始辅音的舌尖动作。"}],"memoryTip":"/l/ 要碰到，/r/ 不要碰到。"}', 21, TRUE),
('unit_compare_22', 'phoneme-compare', 'PHONEME_COMPARE', '近音 /j/ 与 /w/', '{"category":"近音对比","title":"/j/ 和 /w/","description":"/j/ 舌前部抬高，/w/ 先圆唇。","phonemes":[{"phonemeId":"p_c_23","ipa":"/j/","description":"像 yes 开头的轻滑音。","mouth":{"type":"smile"},"audioUrl":null,"examples":["yes","young"]},{"phonemeId":"p_c_24","ipa":"/w/","description":"双唇先收圆，再滑向元音。","mouth":{"type":"closed"},"audioUrl":null,"examples":["we","water"]}],"audioPairs":[{"left":"yes","right":"west","tip":"west 开头先圆唇。"},{"left":"young","right":"one","tip":"注意 /j/ 的舌前部滑动。"}],"memoryTip":"/j/ 靠舌前部，/w/ 先圆唇。"}', 22, TRUE),
('unit_compare_23', 'phoneme-compare', 'PHONEME_COMPARE', '音组 /tr/ 与 /dr/', '{"category":"破擦音组对比","title":"/tr/ 和 /dr/","description":"两者动作相近，/tr/ 清，/dr/ 浊。","phonemes":[{"phonemeId":"p_c_25","ipa":"/tr/","description":"清音组，释放后迅速滑向 /r/。","mouth":{"type":"closed"},"audioUrl":null,"examples":["tree","train"]},{"phonemeId":"p_c_26","ipa":"/dr/","description":"浊音组，声带振动更明显。","mouth":{"type":"closed"},"audioUrl":null,"examples":["dress","dream"]}],"audioPairs":[{"left":"tree","right":"dream","tip":"dream 起始有浊音振动。"},{"left":"train","right":"drain","tip":"听清浊和送气。"}],"memoryTip":"/tr/ 更清更冲，/dr/ 带振动。"}', 23, TRUE),
('unit_compare_24', 'phoneme-compare', 'PHONEME_COMPARE', '音组 /ts/ 与 /dz/', '{"category":"破擦音组对比","title":"/ts/ 和 /dz/","description":"常见于复数或第三人称词尾，/ts/ 清，/dz/ 浊。","phonemes":[{"phonemeId":"p_c_27","ipa":"/ts/","description":"清破擦音组，短促收住。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["cats","lights"]},{"phonemeId":"p_c_28","ipa":"/dz/","description":"浊破擦音组，带声带振动。","mouth":{"type":"relaxed"},"audioUrl":null,"examples":["beds","cards"]}],"audioPairs":[{"left":"cats","right":"cards","tip":"cards 结尾带浊音。"},{"left":"lights","right":"leads","tip":"听词尾清浊，不要加额外元音。"}],"memoryTip":"词尾轻快收住，清浊跟前一个音有关。"}', 24, TRUE);
